import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- COMPONENTS ---

// 1. Navbar: Kat-chouf ch7al men 7aja f-l-panier (cartCount)
const Navbar = ({ cartCount }) => (
  <nav className="bg-white shadow-sm sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="w-full px-6 md:px-12"> 
      <div className="flex justify-between items-center h-20">

        {/* Logo FastDélice 🍴 */}
        <Link to="/" className="flex items-center space-x-3 group">
          <div className="bg-orange-600 p-2.5 rounded-2xl shadow-lg transform group-hover:rotate-12 transition duration-300">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
            </svg>
          </div>
          <div className="flex flex-col text-left">
            <span className="font-black text-2xl text-gray-900 leading-none tracking-tight">
              FAST<span className="text-orange-600">DÉLICE</span>
            </span>
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Cuisine Raffinée</span>
          </div>
        </Link>

        {/* Navigation Links */}
        <div className="hidden lg:flex items-center space-x-10 font-bold text-gray-500 uppercase text-xs tracking-widest">
          <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
        </div>

        {/* Right Side: Panier (mktoub) & Connexion */}
        <div className="flex items-center space-x-8">
          <Link to="/panier" className="relative group flex items-center text-gray-700 hover:text-orange-600 transition">
            <div className="relative p-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              <span className="absolute top-0 right-0 bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center border-2 border-white">{cartCount}</span>
            </div>
            <span className="font-black ml-1 text-xs uppercase tracking-widest">Panier</span>
          </Link>

          <Link to="/login" className="bg-gray-900 text-white px-7 py-3 rounded-xl hover:bg-orange-600 transition duration-300 font-black text-xs uppercase tracking-widest">
            Connexion
          </Link>
        </div>
      </div>
    </div>
  </nav>
);

// 2. Home Page: Full Height Hero & Testimonials
const Home = () => (
  <div className="w-full">
    <div className="relative h-[calc(100vh-80px)] w-full flex items-center justify-center text-center text-white overflow-hidden">
      <div className="absolute inset-0 bg-black/40 z-10"></div>
      <div className="absolute inset-0 z-0">
        <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" alt="Hero" className="w-full h-full object-cover" />
      </div>
      <div className="relative z-20 px-4 max-w-5xl">
        <h1 className="text-7xl md:text-9xl font-black mb-6 tracking-tighter drop-shadow-2xl italic">Fast<span className="text-orange-500">Délice</span></h1>
        <p className="text-xl md:text-3xl mb-10 font-medium text-gray-100 italic">L'art de la cuisine rapide et raffinée.</p>
        <Link to="/menu" className="bg-orange-600 hover:bg-white hover:text-orange-600 text-white px-12 py-5 rounded-2xl text-xl font-black transition-all duration-300 shadow-2xl inline-block uppercase tracking-widest">Découvrir le Menu</Link>
      </div>
    </div>

    {/* Section Avis Clients */}
    <div className="bg-white py-24 px-6 border-t border-gray-50">
      <div className="max-w-6xl mx-auto text-center">
        <h2 className="text-4xl font-black text-gray-900 mb-16 italic">Ce que nos clients disent</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10 text-left">
          {[{ name: "Sarah B.", text: "La meilleure pizza!", stars: "⭐⭐⭐⭐⭐" }, { name: "Ahmed L.", text: "Livraison rapide!", stars: "⭐⭐⭐⭐⭐" }, { name: "Youssef M.", text: "Qualité top.", stars: "⭐⭐⭐⭐" }].map((avis, i) => (
            <div key={i} className="bg-orange-50/50 p-10 rounded-[2.5rem] border border-orange-100 hover:bg-white hover:shadow-2xl transition duration-500">
              <div className="text-orange-500 mb-4 text-sm">{avis.stars}</div>
              <p className="text-gray-700 text-lg mb-8 italic italic">"{avis.text}"</p>
              <h4 className="font-black text-gray-900 uppercase text-xs tracking-widest">— {avis.name}</h4>
            </div>
          ))}
        </div>
      </div>
    </div>
  </div>
);

// 3. Menu Page: Recherche + Modal de choix (Sur place/Emporter)
const Menu = ({ categories, addToCart }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDish, setSelectedDish] = useState(null);
  const navigate = useNavigate();

  const filteredItems = categories.flatMap(cat => 
    cat.dishes.map(dish => ({ ...dish, categoryName: cat.name }))
  ).filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const confirmOrder = (type) => {
    addToCart({ ...selectedDish, orderType: type });
    setSelectedDish(null);
    navigate('/panier'); // Redirect to Panier after choice
  };

  return (
    <div className="min-h-screen py-20 px-6 bg-gray-50 text-center">
      <div className="max-w-7xl mx-auto">
        <h2 className="text-5xl font-black text-gray-900 mb-12 uppercase tracking-tighter italic">Notre Carte</h2>

        {/* Search Bar */}
        <div className="max-w-xl mx-auto mb-16 relative">
          <input 
            type="text" placeholder="Rechercher une pizza, un tacos..." 
            className="w-full px-14 py-5 rounded-2xl bg-white shadow-xl border-none outline-none focus:ring-4 focus:ring-orange-100 font-bold transition text-gray-700"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          {filteredItems.map(item => (
            <div key={item.id} className="bg-white rounded-[2.5rem] shadow-xl border border-gray-100 overflow-hidden hover:scale-105 transition duration-500">
              <div className="h-64 bg-orange-50 flex items-center justify-center text-7xl">
                {item.categoryName.toLowerCase().includes('pizza') ? '🍕' : '🌮'}
              </div>
              <div className="p-8">
                <h3 className="text-2xl font-black text-gray-800 mb-6">{item.name}</h3>
                <div className="flex items-center justify-between mt-4">
                    <span className="text-2xl font-black text-green-600">{item.price} DH</span>
                    <button 
                      onClick={() => setSelectedDish(item)}
                      className="bg-gray-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase hover:bg-orange-600 transition shadow-lg"
                    >
                      Commander
                    </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Choice Modal (Sur Place / Emporter) */}
      {selectedDish && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl text-center transform scale-100 animate-in fade-in zoom-in duration-300">
            <h3 className="text-3xl font-black text-gray-900 mb-2 italic">Excellent choix!</h3>
            <p className="text-gray-500 mb-8 font-bold uppercase text-[10px] tracking-widest italic">Où voulez-vous manger votre {selectedDish.name}?</p>
            <div className="space-y-4">
              <button onClick={() => confirmOrder('Sur Place')} className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black text-lg hover:bg-orange-700 transition shadow-lg">🍽️ Sur Place</button>
              <button onClick={() => confirmOrder('Emporter')} className="w-full py-5 bg-gray-900 text-white rounded-2xl font-black text-lg hover:bg-black transition shadow-lg">🥡 À Emporter</button>
              <button onClick={() => setSelectedDish(null)} className="w-full py-3 text-gray-400 font-bold text-xs uppercase">Annuler</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// 4. Panier Page: Summary of items
const PanierPage = ({ cart }) => (
  <div className="min-h-screen py-24 px-6 max-w-4xl mx-auto">
    <h2 className="text-5xl font-black text-gray-900 mb-12 italic uppercase text-center tracking-tighter">Récapitulatif</h2>
    {cart.length === 0 ? (
      <div className="text-center py-20 text-gray-300 font-black text-4xl italic">Votre panier est vide 🛒</div>
    ) : (
      <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-gray-100">
        {cart.map((item, index) => (
          <div key={index} className="flex justify-between items-center py-6 border-b border-gray-50 last:border-0">
            <div>
              <h3 className="text-2xl font-black text-gray-800">{item.name}</h3>
              <span className="bg-orange-100 text-orange-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">{item.orderType}</span>
            </div>
            <span className="text-2xl font-black text-orange-600">{item.price} DH</span>
          </div>
        ))}
        <div className="mt-10 pt-10 border-t-4 border-gray-900 flex justify-between items-center">
          <span className="text-3xl font-black italic">TOTAL:</span>
          <span className="text-4xl font-black text-green-600">{cart.reduce((total, item) => total + parseFloat(item.price), 0)} DH</span>
        </div>
        <button className="w-full mt-12 bg-gray-900 text-white py-6 rounded-[2rem] font-black text-xl hover:bg-orange-600 transition shadow-2xl">CONFIRMER LA COMMANDE</button>
      </div>
    )}
  </div>
);

// --- MAIN APP ---
function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.error(err));
  }, []);

  const addToCart = (item) => setCart([...cart, item]);

  return (
    <Router>
      <div className="min-h-screen bg-white flex flex-col font-sans">
        <Navbar cartCount={cart.length} />
        <div className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} />} />
            <Route path="/panier" element={<PanierPage cart={cart} />} />
            <Route path="/login" element={<div className="h-screen flex items-center justify-center font-black text-3xl">Page Login...</div>} />
          </Routes>
        </div>
        <footer className="bg-gray-50 border-t border-gray-100 py-12 text-center text-gray-400 font-bold uppercase tracking-[0.3em] text-[10px]">
          © 2026 FAST DÉLICE. TOUS DROITS RÉSERVÉS.
        </footer>
      </div>
    </Router>
  );
}

export default App;
